// Hard gate #1: refuse anything that does not look like a well-formed merge op.
const j = $input.first().json || {};
const need = ['objectType', 'primaryId', 'secondaryId'];
const missing = need.filter(k => !j[k]);
if (missing.length) throw new Error(`Merge payload is missing: ${missing.join(', ')}`);
if (!['contacts','companies','deals'].includes(String(j.objectType)))
  throw new Error(`Unsupported objectType "${j.objectType}"`);
if (String(j.primaryId) === String(j.secondaryId))
  throw new Error(`Refusing to merge record ${j.primaryId} into itself`);
if (!/^\d+$/.test(String(j.primaryId)) || !/^\d+$/.test(String(j.secondaryId)))
  throw new Error('HubSpot object IDs must be numeric');

const cfg = j.config || {};
const READ = {
  contacts: ['email','firstname','lastname','phone','mobilephone','company','createdate',
             'lastmodifieddate','hs_merged_object_ids','dedupe_status','dedupe_merged_from'],
  companies:['name','domain','website','phone','country','createdate','hs_lastmodifieddate',
             'hs_merged_object_ids','dedupe_status','dedupe_merged_from'],
  deals:    ['dealname','amount','closedate','dealstage','pipeline','createdate',
             'hs_lastmodifieddate','hs_merged_object_ids','dedupe_status','dedupe_merged_from'],
};

return [{ json: {
  ...j,
  primaryId: String(j.primaryId),
  secondaryId: String(j.secondaryId),
  readProps: READ[j.objectType],
  dryRun: j.dryRun !== false && cfg.dryRun !== false,
  approvedBy: j.approvedBy || null,
  slackChannel: cfg.slackChannel || '#crm-hygiene',
  startedAt: new Date().toISOString(),
} }];

const j = $input.first().json;
return [{ json: {
  ok: true, outcome: 'dry_run',
  detail: `DRY RUN — would merge ${j.objectType} ${j.secondaryId} → ${j.primaryId} (score ${j.score ?? 'n/a'})`,
  merged: false, primaryId: j.primaryId, secondaryId: j.secondaryId,
} }];

const j = $('🛡️ Validate Payload').first().json;
const e = $input.first().json || {};
return [{ json: { ok:false, outcome:'failed', merged:false,
