  blockReason:'Could not re-read the records before merging',
  detail:String(e.error?.message || e.message || JSON.stringify(e)).slice(0,500),
  alertText:`:x: *Merge aborted — could not re-read records*\n${j.objectType} ${j.secondaryId} → ${j.primaryId}\n\`\`\`${String(e.error?.message || e.message).slice(0,300)}\`\`\`` } }];

