function s(v){ return (v === null || v === undefined) ? '' : String(v).trim(); }
function blank(v){ return s(v) === '' || s(v).toLowerCase() === 'null'; }
function collapse(v){ return s(v).replace(/[\s ]+/g, ' ').trim(); }

// ---- EMAIL ----------------------------------------------------------------
const EMAIL_RE = /^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$/;

function cleanEmail(raw){
  const out = {clean:'', norm:'', domain:'', local:'', valid:false, flags:[]};
  let e = s(raw).toLowerCase().replace(/[\s​]/g,'').replace(/^mailto:/,'');
  e = e.replace(/^[<("']+/,'').replace(/[>)"'.,;]+$/,'');
  if (!e) return out;
  const at = e.lastIndexOf('@');
  if (at < 1 || at === e.length-1){ out.clean=e; out.flags.push('email_malformed'); return out; }
  let local = e.slice(0,at), domain = e.slice(at+1);
  if (domain.endsWith('.')) domain = domain.slice(0,-1);
  // common typo fixes on the TLD only (conservative)
  const TYPO = {'gmail.co':'gmail.com','gmial.com':'gmail.com','gmai.com':'gmail.com',
    'gmail.con':'gmail.com','hotmial.com':'hotmail.com','yahho.com':'yahoo.com',
    'outlok.com':'outlook.com','hotmail.con':'hotmail.com','yahoo.con':'yahoo.com'};
  if (TYPO[domain]){ out.flags.push('email_typo_fixed:'+domain); domain = TYPO[domain]; }
  out.clean  = local + '@' + domain;
  out.local  = local;
  out.domain = domain;
  out.valid  = EMAIL_RE.test(out.clean) && domain.includes('.');
  if (!out.valid) out.flags.push('email_invalid_syntax');
  // normalised form used ONLY for duplicate matching, never written back
  let nl = local;
  if (domain === 'gmail.com' || domain === 'googlemail.com'){
    nl = nl.split('+')[0].replace(/\./g,'');
  } else {
    nl = nl.split('+')[0];
  }
  out.norm = out.valid ? (nl + '@' + (domain === 'googlemail.com' ? 'gmail.com' : domain)) : '';
  const base = local.split('+')[0].replace(/[._-]/g,'');
  if (ROLE_LOCAL.has(local.split('+')[0]) || ROLE_LOCAL.has(base)) out.flags.push('role_address');
  if (DISPOSABLE.some(d => domain.includes(d))) out.flags.push('disposable_domain');
  if (FREE_MAIL.has(domain)) out.flags.push('free_mail_domain');
  if (/^(test|asdf|qwerty|aaa|xxx|abc|none|na|n\/a|noemail)/.test(local)) out.flags.push('email_looks_fake');
  return out;
}

// ---- PHONE ----------------------------------------------------------------
function cleanPhone(raw, defaultCountry){
  const out = {e164:'', clean:'', valid:false, flags:[]};
  let p = s(raw);
  if (!p) return out;
  const ext = p.match(/(?:ext|x|extension|#)\s*\.?\s*(\d{1,6})\s*$/i);
  if (ext){ out.ext = ext[1]; p = p.slice(0, ext.index); }
  let plus = /^\s*\+/.test(p) || /^\s*00\d/.test(p);
  let digits = p.replace(/\D/g,'');
  if (!digits){ out.flags.push('phone_no_digits'); return out; }
  if (/^00/.test(p.replace(/\D/g,'').slice(0,2)) && /^\s*00/.test(p.trim())){
    digits = digits.replace(/^00/,''); plus = true;
  }
  const cc = DIAL[s(defaultCountry).toUpperCase()] || '';
  if (!plus){
    // national format -> prepend the default country dial code
    if (cc === '1' && digits.length === 11 && digits.startsWith('1')) { /* already 1NXXXXXXXXX */ }
    else if (cc && digits.length <= 11){
      digits = digits.replace(/^0+/, '');            // strip national trunk prefix
      if (!digits.startsWith(cc)) digits = cc + digits;
    } else if (!cc){
      out.flags.push('phone_no_country_context');
    }
  }
  if (digits.length < 8 || digits.length > 15){
    out.flags.push('phone_invalid_length');
    out.clean = '+' + digits;
    return out;
  }
  if (/^(\d)\1+$/.test(digits) || /^(?:0123456789|1234567890)/.test(digits)){
    out.flags.push('phone_looks_fake');
  }
  out.e164  = '+' + digits;
  out.clean = out.e164;
  out.valid = out.flags.length === 0;
  return out;
}

// ---- NAMES / CASING -------------------------------------------------------
function titleCaseWord(w){
  if (!w) return w;
  const upper = w.toUpperCase().replace(/[^A-Z&./]/g,'');
  if (ACRONYMS.has(w.toUpperCase()) || ACRONYMS.has(upper)) return w.toUpperCase();
  if (/\d/.test(w)) return w;                                   // keep 3M, H2O, 24/7
  let t = w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
  t = t.replace(/^(mc)([a-z])/i,  (m,a,b)=> 'Mc' + b.toUpperCase());
  t = t.replace(/^(mac)([a-z]{2})/i,(m,a,b)=> 'Mac'+ b.charAt(0).toUpperCase()+b.slice(1));
  t = t.replace(/^(o')([a-z])/i,  (m,a,b)=> "O'" + b.toUpperCase());
  t = t.replace(/^(d')([a-z])/i,  (m,a,b)=> "d'" + b.toUpperCase());
  t = t.replace(/-([a-z])/g,      (m,b)  => '-'  + b.toUpperCase());
  return t;
}

function smartCase(raw, opts){
  const o = opts || {};
  let v = collapse(raw);
  if (!v) return '';
  const isAllCaps = v === v.toUpperCase() && /[A-Z]{2,}/.test(v);
  const isAllLower = v === v.toLowerCase() && /[a-z]{2,}/.test(v);
  if (!o.force && !isAllCaps && !isAllLower) return v;   // respect deliberate casing
  const words = v.split(' ');
  return words.map((w,i) => {
    const lw = w.toLowerCase();
    if (i > 0 && SMALL_WORDS.has(lw) && !o.keepSmall) return lw;
    return titleCaseWord(w);
  }).join(' ');
}

function cleanPersonName(raw){
  let v = collapse(raw).replace(/[",;]+/g,' ').replace(/\s+/g,' ').trim();
  v = v.replace(/^(mr|mrs|ms|miss|dr|prof|eng|sir)\.?\s+/i, '');
  if (!v) return {clean:'', flags:[]};
  const flags = [];
  if (/^[^A-Za-zÀ-ɏ؀-ۿ]+$/.test(v)) flags.push('name_not_alphabetic');
  if (/(test|asdf|qwerty|unknown|n\/a|none|xxx)/i.test(v) && v.length <= 8) flags.push('name_looks_fake');
  if (/https?:\/\/|www\.|@/.test(v)) flags.push('name_contains_url_or_email');
  return {clean: smartCase(v), flags};
}

// ---- COMPANY --------------------------------------------------------------
function normCompany(raw){
  let v = collapse(raw).toLowerCase();
  if (!v) return '';
  v = v.replace(/[‘’“”]/g,"'").replace(/&/g,' and ');
  v = v.replace(/[.,;:()\[\]\/\\'"`]/g,' ').replace(/\s+/g,' ').trim();
  let toks = v.split(' ').filter(Boolean);
  while (toks.length > 1 && LEGAL_SUFFIX.has(toks[toks.length-1])) toks.pop();
  toks = toks.filter(t => !LEGAL_SUFFIX.has(t) || toks.length === 1);
  return toks.join(' ').trim();
}

function cleanCompanyName(raw){
  const v = collapse(raw).replace(/[",;]+$/,'').trim();
  if (!v) return {clean:'', flags:[]};
  const flags = [];
  if (/^(unknown|n\/a|none|test|asdf|-{1,})$/i.test(v)) flags.push('company_looks_fake');
  return {clean: smartCase(v, {keepSmall:false}), flags};
}

function normDomain(raw){
  let d = s(raw).toLowerCase().trim();
  if (!d) return '';
  d = d.replace(/^https?:\/\//,'').replace(/^www\d?\./,'').split('/')[0].split('?')[0]
       .split('#')[0].split(':')[0].replace(/\.$/,'');
  if (!d.includes('.') || /\s/.test(d)) return '';
  return d;
}

// ---- GEO ------------------------------------------------------------------
function normCountry(raw){
  const v = collapse(raw);
  if (!v) return {clean:'', iso:'', flags:[]};
  const k = v.toLowerCase().replace(/\./g,'').trim();
  if (/^[A-Za-z]{2}$/.test(v) && Object.values(COUNTRY).includes(v.toUpperCase()))
    return {clean:v.toUpperCase(), iso:v.toUpperCase(), flags:[]};
  const iso = COUNTRY[k] || COUNTRY[k.replace(/^the /,'')] || '';
  if (!iso) return {clean:v, iso:'', flags:['country_unmapped']};
  return {clean:iso, iso, flags:[]};
}

function normState(raw, iso){
  const v = collapse(raw);
  if (!v) return {clean:'', flags:[]};
  if (iso !== 'US' && iso !== 'CA') return {clean:v, flags:[]};
  if (/^[A-Za-z]{2}$/.test(v)) return {clean:v.toUpperCase(), flags:[]};
  const code = US_STATE[v.toLowerCase()];
  return code ? {clean:code, flags:[]} : {clean:v, flags:['state_unmapped']};
}

// ---- SCORING --------------------------------------------------------------
function completeness(props, weights){
  let got = 0, total = 0;
  const missing = [];
  for (const [f, w] of Object.entries(weights)){
    total += w;
    if (!blank(props[f])) got += w; else missing.push(f);
  }
  return {score: total ? Math.round((got/total)*100) : 0, missing};
}

function pick(obj, keys){ const o = {}; for (const k of keys) if (k in obj) o[k] = obj[k]; return o; }
function uniq(a){ return Array.from(new Set(a.filter(Boolean))); }
function dayDiff(a, b){
  const x = Date.parse(a), y = Date.parse(b);
  if (isNaN(x) || isNaN(y)) return null;
  return Math.abs(x - y) / 86400000;
}
// ============================ END LIB =======================================

// ===========================================================================
//  HARD GATE #2 — re-validate against LIVE HubSpot data, not the snapshot the
//  detector scored minutes (or, after an approval, hours) ago.
//  A HubSpot merge cannot be undone, so every check here fails CLOSED.
// ===========================================================================
const job  = $('🛡️ Validate Payload').first().json;
const resp = $input.first().json || {};
const rows = resp.results || [];

const byId = new Map(rows.map(r => [String(r.id), r]));
const primary   = byId.get(job.primaryId);
const secondary = byId.get(job.secondaryId);

const blocks = [];
if (!primary)   blocks.push(`Primary ${job.primaryId} no longer exists (deleted or already merged away).`);
if (!secondary) blocks.push(`Secondary ${job.secondaryId} no longer exists (deleted or already merged away).`);
if (resp.numErrors) blocks.push(`HubSpot returned ${resp.numErrors} read error(s).`);

if (primary && secondary) {
  const pp = primary.properties || {}, sp = secondary.properties || {};

  if (primary.archived || secondary.archived) blocks.push('One of the records is archived.');

  for (const [lbl, props] of [['primary', pp], ['secondary', sp]]) {
    if (s(props.dedupe_status) === 'do_not_merge')
      blocks.push(`The ${lbl} record is flagged do_not_merge.`);
  }

  const pm = s(pp.hs_merged_object_ids).split(';').map(x => x.trim());
  const sm = s(sp.hs_merged_object_ids).split(';').map(x => x.trim());
  if (pm.includes(job.secondaryId) || sm.includes(job.primaryId))
    blocks.push('These two records have already been merged.');

  // --- re-verify the evidence that justified an automatic merge ----------
  if (job.tier === 'auto') {
    if (job.objectType === 'contacts') {
      const a = cleanEmail(pp.email).norm, b = cleanEmail(sp.email).norm;
      if (!a || !b || a !== b)
        blocks.push(`Auto-merge evidence no longer holds: emails are now "${pp.email || '∅'}" vs "${sp.email || '∅'}".`);
    }
    if (job.objectType === 'companies') {
      const a = normDomain(pp.domain || pp.website), b = normDomain(sp.domain || sp.website);
      if (!a || !b || a !== b)
        blocks.push(`Auto-merge evidence no longer holds: domains are now "${a || '∅'}" vs "${b || '∅'}".`);
    }
    if (job.objectType === 'deals')
      blocks.push('Deals are never auto-merged — this op should have gone to approval.');
  }
}

const label = (o) => {
  const p = (o && o.properties) || {};
  if (job.objectType === 'contacts')  return `${s(p.firstname)} ${s(p.lastname)}`.trim() || s(p.email) || job.primaryId;
  if (job.objectType === 'companies') return s(p.name) || s(p.domain) || job.primaryId;
  return s(p.dealname) || job.primaryId;
};

return [{ json: {
  ...job,
  safe: blocks.length === 0,
  blocks,
  blockReason: blocks.join(' '),
  primaryLabel: label(primary),
  secondaryLabel: label(secondary),
  primaryMergedFrom: s(primary?.properties?.dedupe_merged_from),
  alertText: blocks.length
    ? `:no_entry: *Merge blocked by a safety check*\n${job.objectType} \`${job.secondaryId}\` → \`${job.primaryId}\`\n` +
      blocks.map(b => `• ${b}`).join('\n')
    : '',
} }];

const j = $('🛡️ Live Safety Pre-Checks').first().json;
return [{ json: { ok:true, outcome:'blocked', merged:false,
  primaryId:j.primaryId, secondaryId:j.secondaryId, objectType:j.objectType,
  detail:j.blockReason } }];

const j = $('🛡️ Live Safety Pre-Checks').first().json;
const e = $input.first().json || {};
const raw = String(e.error?.message || e.message || JSON.stringify(e));
const code = Number(e.error?.httpCode || e.statusCode || 0);

let verdict = 'Merge did not happen — safe to retry after investigating.';
let needsHuman = false;
if (/404|not ?found/i.test(raw)) verdict = 'One of the records disappeared between the safety check and the merge. Nothing was merged.';
else if (/409|conflict/i.test(raw)) verdict = 'HubSpot refused the merge (conflict). Usually the objects are in different portals or one is already merged.';
else if (/429|rate/i.test(raw)) verdict = 'Rate limited. Nothing was merged — it will be retried on the next run.';
else if (/401|403/i.test(raw)) { verdict = 'Credential/scope problem: the private app needs write scope on this object.'; needsHuman = true; }
else if (/timeout|ETIMEDOUT|ECONNRESET|socket hang up/i.test(raw)) {
  verdict = 'The request timed out. HubSpot MAY have applied the merge — verify both records in HubSpot before retrying.';
  needsHuman = true;
}

return [{ json: { ok:false, outcome:'failed', merged:false, needsHuman,
  primaryId:j.primaryId, secondaryId:j.secondaryId, objectType:j.objectType,
  detail:`${verdict} (${raw.slice(0,300)})`,
  alertText:`${needsHuman ? ':rotating_light:' : ':warning:'} *Merge failed* — ${j.objectType} \`${j.secondaryId}\` → \`${j.primaryId}\`\n${verdict}\n\`\`\`${raw.slice(0,400)}\`\`\`` } }];

const j = $('🛡️ Live Safety Pre-Checks').first().json;
const merged = $('HubSpot: ⚠️ MERGE').first().json || {};
